with exploded as (select id, service, host, level, attr_key, attr_value from app_logs lateral view explode(context) t as attr_key, attr_value), valid as (select *, substring(service, 1, 3) as service_prefix, coalesce(attr_key, 'N/A') as attr_key_clean from exploded where attr_key in ('version', 'region', 'trace')), matched_keys as (select id, host from valid except select id, host from app_logs where host = 'h4'), kept_rows as (select s.* from valid s inner join matched_keys k on s.id = k.id and s.host = k.host), base as (select service, host, level, attr_key, attr_value, service_prefix, attr_key_clean, case when level = 'ERROR' then 1 else 0 end as is_error, concat_ws('-', service, attr_key) as service_attr_key_key, coalesce(attr_key, 'NONE') as attr_key_filled from kept_rows where attr_key is not null), scored as (select service_prefix, attr_key_clean, attr_key_filled, cume_dist() over (order by is_error desc) as is_error_cume_dist, rank() over (order by is_error) as is_error_rank, dense_rank() over (partition by host order by is_error nulls last) as is_error_dense_rank, max(is_error) over (partition by attr_key) as attr_key_max_is_error, rank() over (partition by host order by is_error desc nulls first) as is_error_rank_2 from base), enriched as (select *, dense_rank() over (order by attr_key_max_is_error desc nulls last) as attr_key_max_is_error_dense_rank, rank() over (order by is_error_cume_dist desc) as is_error_cume_dist_rank from scored where is_error_dense_rank >= 3), base_app_logs as (select service_prefix, attr_key_clean, is_error_cume_dist, is_error_rank, is_error_dense_rank, is_error_rank_2, attr_key_max_is_error_dense_rank, is_error_cume_dist_rank, round(is_error_dense_rank / attr_key_max_is_error_dense_rank, 2) as is_error_dense_rank_per_attr_key_max_is_error_dense_rank from enriched where is_error_cume_dist > 0.21) select case when is_error_rank_2 >= 7 then 'PREMIUM' else 'STANDARD' end as is_error_rank_2_tier, case when is_error_cume_dist >= 0.68 then 'LARGE' else 'SMALL' end as is_error_cume_dist_tier, count(*) as cnt, count(*) as row_count, percentile_approx(is_error_dense_rank, array(0.25, 0.5, 0.75)) as is_error_dense_rank_quartiles from base_app_logs group by case when is_error_rank_2 >= 7 then 'PREMIUM' else 'STANDARD' end, case when is_error_cume_dist >= 0.68 then 'LARGE' else 'SMALL' end
